                throw new InvalidCastException($"'{operation}' not supported between instances of '{PyTypeName(__type_of(a))}' and '{PyTypeName(__type_of(b))}'");
            if (operation[0] == '>') (a, b) = (b, a);
            return SetLe(a, b) && (operation.Length == 2 || !SetLe(b, a));
