                    string name = type == typeof(Typhon.Stdlib.ast.AST) ? "ast.AST" : PyTypeName(type);
                    throw new InvalidCastException($"{name}() accepts {count} positional sub-pattern{(count == 1 ? "" : "s")} ({positional} given)");
                }
